```openscad
// Wall-mounted 10 mL syringe holder (tip-down, upright)
// Print orientation: rests on XY plane at z = 0, builds +Z, centred in X/Y.
// Back face (y = 15) is the wall side; syringe slides in from the front (y = -15).

// ---- Block dimensions (measured with calipers) ----
block_w = 50;   // X width
block_d = 30;   // Y depth
block_h = 40;   // Z height

// ---- Barrel channel (16.5 mm wide vertical slot, full height) ----
ch_half_w = 16.5 / 2;   // 8.25 mm half-width
ch_back_r = 8.25;       // radius of the half-circle at the back end
ch_back_cy = 0;         // centre of the back half-circle in Y (y = 0)
ch_front_y = -15;       // straight sides run forward to the front face

// ---- Finger-flange slot (cut in from the front face) ----
flange_w = 34;          // X width, centred
flange_h = 2.6;         // Z thickness (2 mm flange + clearance)
flange_z0 = 30;         // bottom of slot
flange_z1 = 32.6;       // top of slot
flange_y0 = -15;        // starts at the front face
flange_y1 = 11;         // extends back to y = 11

// ---- M4 wall-screw clearance holes (through, along Y) ----
screw_d = 4.5;          // clearance hole diameter
screw_z = 15;           // hole centre height
screw_x = [-19, 19];    // hole centre X positions

// ---- Curvature resolution ----
$fn = 64;

// =====================================================================
// 1. Base block, centred on origin in X and Y, sitting on z = 0
// =====================================================================
block = translate([-block_w / 2, -block_d / 2, 0])
    cube([block_w, block_d, block_h]);

// =====================================================================
// 2. Barrel channel: half-circle (back) + rectangle (forward to front)
//    Union of the two pieces gives a smooth "D" cross-section.
//    Both pieces extend 1 mm past the top/bottom faces so the cut is
//    clean and no faces end up exactly coplanar with the block.
// =====================================================================
// 2a. Half-circle at the back (y >= 0), spanning x = -8.25 .. 8.25
half_circle = translate([0, ch_back_cy, 0])
    linear_extrude(height = block_h + 2, center = true)
        circle(r = ch_back_r, $fn = 64);

// 2b. Rectangle from y = 0 back to the front face (y = -15)
channel_rect = translate([-ch_half_w, ch_front_y, -1])
    cube([2 * ch_half_w, -ch_front_y, block_h + 2]);   // y: -15 .. 0

barrel_channel = union() {
    half_circle;
    channel_rect;
}

// =====================================================================
// 3. Finger-flange slot: 34 mm wide, 2.6 mm tall, y = -15 .. 11
//    (extends 1 mm past the front face so the cut is not coplanar)
// =====================================================================
flange_slot = translate([-flange_w / 2, flange_y0 - 1, flange_z0])
    cube([flange_w, flange_y1 - flange_y0 + 1, flange_h]);

// =====================================================================
// 4. M4 screw clearance holes: 4.5 mm dia, through along Y
//    (extend 1 mm past both the front and back faces)
// =====================================================================
screw_holes = for (sx = screw_x)
    translate([sx, -block_d / 2 - 1, screw_z])
        cylinder(h = block_d + 2, r = screw_d / 2, $fn = 64);

// =====================================================================
// Final part: block minus all cutters
// =====================================================================
difference() {
    block;
    barrel_channel;
    flange_slot;
    screw_holes;
}
```

```openscad
// Adapter: phone camera over microscope eyepiece (30 mm OD), printed phone-side down
// All dimensions in mm, measured with calipers.

// ---- Plate ----
plate_x = 80;   // plate length in X
plate_y = 60;   // plate width in Y
plate_t = 3;    // plate thickness (z = 0..3)
cam_hole_d = 12;    // camera through-hole diameter
cam_hole_x = -20;   // camera hole centre X
cam_hole_y = 10;    // camera hole centre Y

// ---- Sleeve (on camera-hole axis) ----
sleeve_od = 36.6;   // sleeve outer diameter
sleeve_z0 = 3;      // sleeve base (sits on plate top)
sleeve_z1 = 31;     // sleeve top (open)
bore1_d = 22;       // lower bore (camera stop) diameter
bore1_z0 = 3;       // lower bore start
bore1_z1 = 11;      // lower bore end
bore2_d = 30.6;     // upper bore (slides over 30 mm eyepiece) diameter
bore2_z0 = 11;      // upper bore start
bore2_z1 = 31;      // upper bore end (open top)

// ---- M3 centring screw holes ----
screw_hole_d = 2.5;   // radial hole diameter
screw_z = 21;         // hole axis height
screw_n = 3;          // number of radial holes
screw_start = 0;      // first hole points +X

$fn = 64;

// ===================== BODY =====================
body = union() {
    // Flat plate on the bed, centred on origin
    translate([-plate_x/2, -plate_y/2, 0])
        cube([plate_x, plate_y, plate_t]);

    // Round sleeve standing on the plate, on the camera-hole axis
    translate([cam_hole_x, cam_hole_y, 0])
        cylinder(h = sleeve_z1, d = sleeve_od, center = false);
};

// ===================== CUTS =====================
cuts = union() {
    // Camera through-hole in the plate (extends 1 mm past each face)
    translate([cam_hole_x, cam_hole_y, -1])
        cylinder(h = plate_t + 2, d = cam_hole_d, center = false);

    // Lower bore (camera stop) - extends 1 mm below plate and 0.5 mm into upper bore
    translate([cam_hole_x, cam_hole_y, bore1_z0 - 1])
        cylinder(h = (bore1_z1 - bore1_z0) + 1.5, d = bore1_d, center = false);

    // Upper bore (slides over eyepiece) - extends 1 mm past open top
    translate([cam_hole_x, cam_hole_y, bore2_z0])
        cylinder(h = (bore2_z1 - bore2_z0) + 1, d = bore2_d, center = false);

    // Three radial 2.5 mm M3 centring-screw holes, 120 deg apart, first in +X
    for (i = [0 : screw_n - 1]) {
        a = screw_start + i * 360 / screw_n;
        // Cylinder axis along local X, rotated about Z by a, centred on sleeve axis
        translate([cam_hole_x, cam_hole_y, screw_z])
        rotate([0, 0, a])
        // Extend 1 mm past the sleeve outer wall on each side
        cylinder(h = sleeve_od + 2, d = screw_hole_d, center = true);
    }
};

// ===================== FINAL PART =====================
difference() {
    body;
    cuts;
}
```

