        cx = (i - (seat_n - 1) / 2) * seat_pitch;   // centred on origin in X
        // Cylindrical portion: z = 12 to z = 20 (extend 0.5 mm past top for clean cut)
        translate([cx, 0, 12])
            cylinder(h = (seat_top_z - 12) + 0.5, d = seat_top_d, $fn = 64);
