// Centred at y = -6 and y = +6, centred in X
// ---------------------------------------------------------------------------
pocket_cut = union() {
    for (py = [-pocket_y, pocket_y]) {
        translate([-pocket_L/2, py - pocket_W/2, -0.5])
            cube([pocket_L, pocket_W, pocket_H + 0.5]);
